class CountOver extends RecursiveTask<Integer> {
    final long[] a; final long limit; final int from, to;

    CountOver(long[] a, long limit, int from, int to) {
        this.a = a; this.limit = limit; this.from = from; this.to = to;
    }

    @Override
    protected Integer compute() {
        if (to - from <= 10_000) {
            int n = 0;
            for (int i = from; i < to; i++) if (a[i] > limit) n++;
            return n;
        }
        int mid = (from + to) >>> 1;
        CountOver left = new CountOver(a, limit, from, mid);
        CountOver right = new CountOver(a, limit, mid, to);
        left.fork();                       // stealable
        int r = right.compute();           // work here
        return left.join() + r;            // then collect
    }
}

int flagged = ForkJoinPool.commonPool().invoke(new CountOver(amounts, 500_000, 0, amounts.length));

