suspend fun countOver(a: LongArray, limit: Long, from: Int, to: Int): Int =
    if (to - from <= 10_000) {
        (from until to).count { a[it] > limit }
    } else coroutineScope {
        val mid = (from + to) ushr 1
        val left = async { countOver(a, limit, from, mid) }   // like fork()
        val right = countOver(a, limit, mid, to)              // like compute()
        left.await() + right                                  // like join()
    }

val flagged = runBlocking(Dispatchers.Default) { countOver(amounts, 500_000, 0, amounts.size) }

