class MaxAmount extends RecursiveTask<Long> {
    final long[] a; final int from, to;

    MaxAmount(long[] a, int from, int to) { this.a = a; this.from = from; this.to = to; }

    @Override
    protected Long compute() {
        if (to - from <= 10_000) {
            long max = Long.MIN_VALUE;
            for (int i = from; i < to; i++) max = Math.max(max, a[i]);
            return max;
        }
        int mid = (from + to) >>> 1;
        MaxAmount left = new MaxAmount(a, from, mid);
        MaxAmount right = new MaxAmount(a, mid, to);
        left.fork();
        long r = right.compute();
        return Math.max(left.join(), r);
    }
}

long max = ForkJoinPool.commonPool().invoke(new MaxAmount(amounts, 0, amounts.length));

